-- ============================================================================
-- Flag Me Down (the standalone mode): 170 countries, each with its flag, its
-- local region, its capital and its map -- the four clues that unlock one by
-- one each round. Countries only (Randy's call; territories, regional flags
-- and organizations stay in Country Monkey and the Thinking Pants category).
-- Every country here has both a flag (public/flags/) and a map (public/maps/).
--
-- Its own table, flag_me_down_countries (like profiler_questions), because a
-- round needs several clues per country. Columns:
--   continent      region key, used to pick believable wrong answers
--   local_region   the region clue shown on the TV ("Western Africa")
--   capital        the real capital, shown at the reveal
--   capital_clue   the capital clue -- the capital itself, unless it contains
--                  the country's name ("Mexico City", "Bissau", "Tunis"),
--                  which would give the answer away
--   accepted_answers  alternate names for the typed final round (Burma, ...)
--   difficulty     1 easy / 2 medium / 3 hard -- a game plays 5 of each, in
--                  that order. Rows: 53 easy, 52 medium, 65 hard.
--
-- Safe to re-run: creates the table if needed, then deletes and re-inserts
-- every row, in a transaction. Touches nothing else.
-- ============================================================================

BEGIN;

CREATE TABLE IF NOT EXISTS flag_me_down_countries (
    name             TEXT PRIMARY KEY,
    continent        TEXT NOT NULL,
    local_region     TEXT NOT NULL,
    capital          TEXT NOT NULL,
    capital_clue     TEXT NOT NULL,
    flag_asset       TEXT NOT NULL,
    map_asset        TEXT NOT NULL,
    accepted_answers TEXT[],
    difficulty       INTEGER NOT NULL
);

DELETE FROM flag_me_down_countries;

INSERT INTO flag_me_down_countries (name, continent, local_region, capital, capital_clue, flag_asset, map_asset, accepted_answers, difficulty)
